/*
 * ATENCIÓN: igual que con el CSS, este es un JS mínimo de reemplazo
 * que solo activa/desactiva el menú de navegación en pantallas
 * pequeñas. Para la entrega, reemplaza este archivo por el
 * bootstrap.bundle.min.js OFICIAL descargado desde
 * https://getbootstrap.com/docs/5.3/getting-started/download/
 * (déjalo con el mismo nombre y en la misma carpeta).
 */
document.addEventListener('DOMContentLoaded', function () {
  var toggler = document.querySelector('.navbar-toggler');
  var menu = document.querySelector('.navbar-nav');
  if (toggler && menu) {
    toggler.addEventListener('click', function () {
      menu.classList.toggle('nav-open');
    });
  }
});
